    public static boolean isVowel(char c) {
        if (c == 'a') {
            return true;
        }
        if (c == 'e') {
            return true;
        }
        if (c == 'i') {
            return true;
        }
        if (c == 'o') {
            return true;
        }
        if (c == 'u') {
            return true;
        }
        return c == 'A' || c == 'E' || c == 'I';
    }
}

